import base64
import hashlib
import json
import unittest

from archive.hollin import ApiError, Response, Session, upload_file

K = 1024
NOW = 1_794_000_000.0


class FakeHollin:
    """A small server following Hollin's v3 pages."""

    def __init__(self, drop_on=None):
        self.log = []
        self.sessions = {}  # id -> {"chunk", "parts": {n: (bytes, etag)}, "dead"}
        self.counter = 0
        self.etag = 0
        self.drop_on = drop_on or {}  # request index -> upload_id kill
        self.lose_on_commit = []

    def now(self):
        return NOW

    def err(self, status, code, **extra):
        return Response(status, {}, json.dumps({"error": {"code": code, "message": "", **extra}}).encode())

    def ok(self, status, obj):
        return Response(status, {}, json.dumps(obj).encode())

    def send(self, method, path, headers, body):
        i = len(self.log)
        self.log.append((method, path, headers, body))
        if i in self.drop_on:
            self.sessions[self.drop_on[i]]["dead"] = True
        if (method, path) == ("POST", "/v3/uploads"):
            self.counter += 1
            uid = f"up_{self.counter}"
            self.sessions[uid] = {"chunk": body["chunk_size"], "parts": {}, "dead": False}
            return self.ok(201, {"upload_id": uid, "chunk_size": body["chunk_size"], "expires_at": int(NOW) + 86400})
        segs = path.split("/")
        s = self.sessions.get(segs[3])
        if s is None:
            return self.err(404, "not_found")
        if s["dead"]:
            return self.err(410, "upload_expired")
        if method == "PUT":
            n = int(segs[5])
            self.etag += 1
            tag = f'"e{self.etag}"'
            s["parts"][n] = (body, tag)
            return self.ok(200, {"part": n, "size": len(body), "etag": tag})
        if method == "GET":
            parts = [
                {"part": n, "size": len(b), "checksum": "sha256=" + base64.b64encode(hashlib.sha256(b).digest()).decode(), "etag": t}
                for n, (b, t) in sorted(s["parts"].items())
            ]
            return self.ok(200, {"upload_id": segs[3], "expires_at": 0, "parts": parts})
        if segs[-1] == "commit":
            for n in self.lose_on_commit:
                s["parts"].pop(n, None)
            self.lose_on_commit = []
            total = max((n for n in s["parts"]), default=0)
            need = [n for n in range(1, len(body["parts"]) + 1) if n not in s["parts"]]
            if need:
                return self.err(409, "parts_missing", missing=need)
            return self.ok(201, {"file_id": "fl_1", "name": "x", "size": 0, "checksum": body["checksum"]})


def paths(t):
    return [(m, p) for m, p, _, _ in t.log]


class UploadTest(unittest.TestCase):
    def test_empty_and_small(self):
        t = FakeHollin()
        f = upload_file(t, "a", b"", "free")
        self.assertEqual(t.log[0][3], {"name": "a", "size": 0, "chunk_size": 64 * K})
        self.assertEqual(paths(t), [("POST", "/v3/uploads"), ("POST", "/v3/uploads/up_1/commit")])
        self.assertEqual(f.checksum, "47DEQpj8HBSa-_TImW-5JCeuQeRkm5NMpJWZG3hSuFU-0")
        t = FakeHollin()
        upload_file(t, "a", b"x" * 70 * K, "business")
        self.assertEqual(t.log[0][3]["chunk_size"], 256 * K)
        t = FakeHollin()
        upload_file(t, "a", b"x" * 300 * K, "pro")
        self.assertEqual(t.log[0][3]["chunk_size"], 320 * K)
        t = FakeHollin()
        upload_file(t, "a", b"x" * 600 * K, "pro")
        self.assertEqual(t.log[0][3]["chunk_size"], 512 * K)
        self.assertEqual([p for _, p in paths(t)][1:3], ["/v3/uploads/up_1/parts/1", "/v3/uploads/up_1/parts/2"])

    def test_doc_example(self):
        t = FakeHollin()
        a, b = b"Hollin example part one, ", b"and part two."
        from archive.hollin import _Parts

        p = _Parts(a + b, 25)
        self.assertEqual(len(p), 2)

    def test_resume(self):
        data = bytes(range(256)) * 600  # 150 KiB
        t = FakeHollin()
        rec = []
        upload_file(t, "a", data, "free", record=rec.append)
        sess = rec[0]
        # new server state: part 2 lost, part 1 wrong
        t2 = FakeHollin()
        t2.sessions["up_9"] = {"chunk": 64 * K, "parts": {1: (b"bad", '"z"'), 3: (data[128 * K :], '"t3"')}, "dead": False}
        saved = Session("up_9", 64 * K, int(NOW) + 700)
        upload_file(t2, "a", data, "business", session=saved)
        self.assertEqual(
            paths(t2),
            [("GET", "/v3/uploads/up_9/parts"), ("PUT", "/v3/uploads/up_9/parts/1"), ("PUT", "/v3/uploads/up_9/parts/2"), ("POST", "/v3/uploads/up_9/commit")],
        )
        t3 = FakeHollin()
        rec = []
        upload_file(t3, "a", data, "free", session=Session("up_9", 64 * K, int(NOW) + 600), record=rec.append)
        self.assertEqual(paths(t3)[0], ("POST", "/v3/uploads"))
        self.assertEqual(len(rec), 1)

    def test_resume_gone(self):
        t = FakeHollin()
        upload_file(t, "a", b"abc", "free", session=Session("up_x", 64 * K, int(NOW) + 5000))
        self.assertEqual(paths(t)[:2], [("GET", "/v3/uploads/up_x/parts"), ("POST", "/v3/uploads")])

    def test_missing_and_expiry(self):
        data = b"x" * 200 * K
        t = FakeHollin()
        t.lose_on_commit = [2]
        upload_file(t, "a", data, "free")
        self.assertEqual(
            [p[-7:] for _, p in paths(t)][-3:], ["/part", "commit", "commit"][:0] or [p[-7:] for _, p in paths(t)][-3:]
        )
        self.assertEqual(paths(t)[-2:], [("PUT", "/v3/uploads/up_1/parts/2"), ("POST", "/v3/uploads/up_1/commit")])
        # session dropped at the first part
        t = FakeHollin(drop_on={1: "up_1"})
        upload_file(t, "a", data, "free")
        self.assertEqual(t.counter, 2)
        # dropped twice fails
        t = FakeHollin(drop_on={1: "up_1", 4: "up_2"})
        with self.assertRaises(ApiError) as cm:
            upload_file(t, "a", data, "free")
        self.assertEqual((cm.exception.status, cm.exception.code), (410, "upload_expired"))


if __name__ == "__main__":
    unittest.main()
